seen AS (
  SELECT e.file, e.tbl, e.id, e.old_link,
    CASE WHEN e.tbl = 'organizations' THEN (SELECT website_url FROM organizations WHERE id = e.id)
         ELSE (SELECT website_url FROM programs WHERE id = e.id) END AS link_now,
    CASE WHEN e.tbl = 'organizations' THEN (SELECT is_public FROM organizations WHERE id = e.id)
         ELSE (SELECT is_public FROM programs WHERE id = e.id) END AS public_now,
    CASE WHEN e.tbl = 'organizations' THEN (SELECT count(*) FROM organizations WHERE id = e.id)
         ELSE (SELECT count(*) FROM programs WHERE id = e.id) END AS row_exists
  FROM expected e
)
SELECT file,
  count(*) AS rows_in_file,
  sum(CASE WHEN link_now = old_link THEN 1 ELSE 0 END) AS matched,
  sum(CASE WHEN link_now = old_link AND public_now = 1 THEN 1 ELSE 0 END) AS matched_public,
  sum(CASE WHEN row_exists = 0 THEN 1 ELSE 0 END) AS row_missing,
  sum(CASE WHEN row_exists = 1 AND (link_now IS NULL OR link_now <> old_link) THEN 1 ELSE 0 END) AS already_changed
FROM seen GROUP BY file ORDER BY file;
